// modules/i18n.js
// ── Internationalisation & Multi-Language Translation ────────────────
//
// Aurafisky serves a global audience. The app supports deep native i18n
// across major world and Indian regional languages (Kannada, Hindi, Tamil,
// Telugu, Marathi, Bengali, Gujarati, Malayalam, Punjabi, Odia, Sanskrit,
// Assamese, Urdu, Spanish, French, German, Italian, Portuguese, Russian,
// Japanese, Korean, Chinese, Arabic, Turkish, Vietnamese, Thai, Indonesian,
// Dutch, Polish, Swedish, Persian, Nepali, Sinhala, Swahili, Tagalog, etc.)
// plus a recursive, client-side DOM & text translation engine.

