/** Detects the active locale from localStorage, URL query, navigator, or fallback. */
export function detectLocale() {
  try {
    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      const q = url.searchParams.get("lang") || url.searchParams.get("locale");
      if (q && SUPPORTED.includes(q)) return q;
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored && SUPPORTED.includes(stored)) return stored;
    }
  } catch (_) {}
  try {
    if (typeof navigator !== "undefined") {
      const nav = (navigator.language || navigator.userLanguage || "").toLowerCase();
      if (nav.startsWith("zh-tw") || nav.startsWith("zh-hk")) return "zh-TW";
      if (nav.startsWith("zh")) return "zh-CN";
      const two = nav.slice(0, 2);
      if (SUPPORTED.includes(two)) return two;
    }
  } catch (_) {}
  return DEFAULT;
}

/** Sets and persists the user locale. */
export function setLocale(locale) {
  if (!SUPPORTED.includes(locale)) return false;
  try {
    if (typeof localStorage !== "undefined") {
      localStorage.setItem(STORAGE_KEY, locale);
    }
  } catch (_) {}
  return true;
}

/** Gets the current locale. */
export function getLocale() {
  return detectLocale();
}

/** Lists all supported locale codes. */
export function supportedLocales() {
  return [...SUPPORTED];
}

/** Checks if a locale is supported. */
export function isSupported(locale) {
  return SUPPORTED.includes(locale);
}

/**
 * Returns translated string for key, falling back to English, then the key itself.
 */
export function t(key, locale = detectLocale()) {
  const dict = DICT[locale] || DICT[DEFAULT] || BASE_EN;
  if (dict && dict[key] !== undefined) return dict[key];
  const en = DICT[DEFAULT] || BASE_EN;
  if (en && en[key] !== undefined) return en[key];
  return key;
}

/**
 * Universal text translation for any string in the UI.
 * Handles direct dictionary matches, phrase lookups, reverse key lookups, and regex patterns.
 */
export function translateText(rawText, locale = detectLocale()) {
  if (!rawText || typeof rawText !== "string") return rawText;
  if (!locale || locale === "en") return rawText;

  const trimmed = rawText.trim();
  if (!trimmed) return rawText;

  // 1. Direct phrase lookup
  const pMap = PHRASES[locale] || {};
  if (pMap[trimmed]) {
    return rawText.replace(trimmed, pMap[trimmed]);
  }

  // Trailing ellipsis handler
  if (trimmed.endsWith("...") || trimmed.endsWith("…")) {
    const withoutDots = trimmed.replace(/\.{3}$|…$/, "").trim();
    if (pMap[withoutDots]) {
      const suffix = trimmed.endsWith("…") ? "…" : "...";
      return rawText.replace(trimmed, pMap[withoutDots] + suffix);
    }
  }

  // 2. Direct dictionary key check
  const fromT = t(trimmed, locale);
  if (fromT && fromT !== trimmed) {
    return rawText.replace(trimmed, fromT);
  }

  // 3. Reverse lookup: lowercase English text -> key -> localized string
  const norm = trimmed.toLowerCase();
  const revKey = EN_PHRASE_TO_KEY[norm];
  if (revKey) {
    const val = t(revKey, locale);
    if (val && val !== BASE_EN[revKey]) {
      return rawText.replace(trimmed, val);
    }
  }

  // Check without dots for reverse key
  if (norm.endsWith("...") || norm.endsWith("…")) {
    const normNoDots = norm.replace(/\.{3}$|…$/, "").trim();
    const revNoDots = EN_PHRASE_TO_KEY[normNoDots];
    if (revNoDots) {
      const val = t(revNoDots, locale);
      if (val && val !== BASE_EN[revNoDots]) {
        const suffix = trimmed.endsWith("…") ? "…" : "...";
        return rawText.replace(trimmed, val + suffix);
      }
    }
  }

  // 4. Dynamic patterns
  // Pattern: Show All (N)
  const showAllMatch = trimmed.match(/^Show All\s*\((\d+)\)$/i);
  if (showAllMatch) {
    const showAllTrans = pMap["Show All"] || t("show_all", locale) || "Show All";
    return rawText.replace(trimmed, `${showAllTrans} (${showAllMatch[1]})`);
  }

  // Pattern: Show Fewer / Show Less
  if (/^Show Fewer$/i.test(trimmed)) {
    const trans = pMap["Show fewer"] || t("show_fewer", locale) || "Show fewer";
    return rawText.replace(trimmed, trans);
  }

  // Pattern: Stop N
  const stopMatch = trimmed.match(/^Stop\s*(\d+)$/i);
  if (stopMatch) {
    const stopTrans = pMap["Stop"] || t("stop", locale) || "Stop";
    return rawText.replace(trimmed, `${stopTrans} ${stopMatch[1]}`);
  }

  // Pattern: Stops (N)
  const stopsMatch = trimmed.match(/^Stops\s*\((\d+)\)$/i);
  if (stopsMatch) {
    const stopsTrans = pMap["Stops"] || t("stops", locale) || "Stops";
    return rawText.replace(trimmed, `${stopsTrans} (${stopsMatch[1]})`);
  }

  // Pattern: Next rain TIME
  const nextRainMatch = trimmed.match(/^(?:🌧️\s*)?Next rain\s+(.+)$/i);
  if (nextRainMatch) {
    const nextRainTrans = pMap["Next rain"] || t("next_rain", locale) || "Next rain";
    return rawText.replace(trimmed, `🌧️ ${nextRainTrans} ${nextRainMatch[1]}`);
  }

  // Pattern: Tailwind / Headwind / Crosswind (+N km/h)
  const windMatch = trimmed.match(/^(Tailwind|Headwind|Crosswind)\s*\(([^)]+)\)$/i);
  if (windMatch) {
    const windTrans = pMap[windMatch[1]] || windMatch[1];
    return rawText.replace(trimmed, `${windTrans} (${windMatch[2]})`);
  }

  // Pattern: Trust score (handles pure English, mixed, or localized)
  // e.g. "🎯 55% trust (temp 62%, wind 52%, precip 47%)" or "55% trust (温度 62%, 风速 52%, precipitation 47%)"
  const trustMatch = trimmed.match(/^(?:🎯\s*)?(\d+)%\s*(?:trust|置信度|ವಿಶ್ವಾಸಾರ್ಹತೆ|विश्वसनीयता|confianza|confiance|Vertrauen|fede|confiança|доверие|信頼度|신뢰도|ثقة)?\s*\((.+)\)$/i);
  if (trustMatch) {
    const pct = trustMatch[1];
    const inner = trustMatch[2];
    const nums = inner.match(/(\d+)%/g);
    if (nums && nums.length >= 3) {
      if (locale === "kn") {
        return rawText.replace(trimmed, `🎯 ${pct}% ವಿಶ್ವಾಸಾರ್ಹತೆ (ತಾಪ ${nums[0]}, ಗಾಳಿ ${nums[1]}, ಮಳೆ ${nums[2]})`);
      } else if (locale === "hi") {
        return rawText.replace(trimmed, `🎯 ${pct}% विश्वसनीयता (ताप ${nums[0]}, हवा ${nums[1]}, वर्षा ${nums[2]})`);
      } else if (locale === "ta") {
        return rawText.replace(trimmed, `🎯 ${pct}% நம்பகத்தன்மை (வெப்பம் ${nums[0]}, காற்று ${nums[1]}, மழை ${nums[2]})`);
      } else if (locale === "te") {
        return rawText.replace(trimmed, `🎯 ${pct}% విశ్వసనీయత (ఉష్ణోగ్రత ${nums[0]}, గాలి ${nums[1]}, వర్షం ${nums[2]})`);
      } else if (locale === "zh-CN") {
        return rawText.replace(trimmed, `🎯 ${pct}% 置信度 (温度 ${nums[0]}, 风速 ${nums[1]}, 降水 ${nums[2]})`);
      } else if (locale === "zh-TW") {
        return rawText.replace(trimmed, `🎯 ${pct}% 置信度 (溫度 ${nums[0]}, 風速 ${nums[1]}, 降水 ${nums[2]})`);
      } else if (locale === "es") {
        return rawText.replace(trimmed, `🎯 ${pct}% confianza (temp ${nums[0]}, viento ${nums[1]}, precip ${nums[2]})`);
      } else {
        const trustLbl = t("trust", locale) || "trust";
        const tempLbl = t("temperature", locale) || "temp";
        const windLbl = t("wind", locale) || "wind";
        const precipLbl = t("precipitation", locale) || "precip";
        return rawText.replace(trimmed, `🎯 ${pct}% ${trustLbl} (${tempLbl} ${nums[0]}, ${windLbl} ${nums[1]}, ${precipLbl} ${nums[2]})`);
      }
    }
  }

  // Pattern: Best time to be outside: ...
  const bestTimeMatch = trimmed.match(/^Best time to be outside:\s*(.+)$/i);
  if (bestTimeMatch) {
    const lbl = t("best_time_to_be_outside", locale) || "Best time to be outside";
    return rawText.replace(trimmed, `${lbl}: ${bestTimeMatch[1]}`);
  }

  // Pattern: Rain expected around ...
  const rainExpMatch = trimmed.match(/^Rain expected around\s*(.+)$/i);
  if (rainExpMatch) {
    const lbl = t("rain_expected_around", locale) || "Rain expected around";
    return rawText.replace(trimmed, `${lbl} ${rainExpMatch[1]}`);
  }

  // Pattern: Rain N% peak over 24h — low concern
  const rainPeakMatch = trimmed.match(/^Rain\s*(\d+)%\s*peak over 24h\s*[—-]\s*low concern$/i);
  if (rainPeakMatch) {
    const rLbl = t("rain", locale) || "Rain";
    const pLbl = t("peak_over_24h", locale) || "peak over 24h — low concern";
    return rawText.replace(trimmed, `${rLbl} ${rainPeakMatch[1]}% ${pLbl}`);
  }

  // Pattern: N% chance within 6 hours — plan around it
  const rain6hMatch = trimmed.match(/^(\d+)%\s*chance within 6 hours\s*[—-]\s*plan around it$/i);
  if (rain6hMatch) {
    const cLbl = t("chance_within_6_hours", locale) || "chance within 6 hours — plan around it";
    return rawText.replace(trimmed, `${rain6hMatch[1]}% ${cLbl}`);
  }

  // Pattern: feels N°
  const feelsMatch = trimmed.match(/\bfeels\s+(\d+)°/i);
  if (feelsMatch) {
    const fLbl = t("feels", locale) || "feels";
    rawText = rawText.replace(feelsMatch[0], `${fLbl} ${feelsMatch[1]}°`);
  }

  // Pattern: (overnight)
  if (trimmed.includes("(overnight)")) {
    const oLbl = t("overnight", locale) || "overnight";
    rawText = rawText.replace("(overnight)", `(${oLbl})`);
  }

  // Pattern: arriving in ~Nh from the DIR
  const arriveMatch = trimmed.match(/arriving in ~(\d+)h from the ([A-Z]+)/i);
  if (arriveMatch) {
    const hours = arriveMatch[1];
    const dir = arriveMatch[2];
    if (locale === "kn") {
      return rawText.replace(arriveMatch[0], `~${hours} ಗಂಟೆಯಲ್ಲಿ ${dir} ನಿಂದ ಬರುತ್ತಿದೆ`);
    } else if (locale === "hi") {
      return rawText.replace(arriveMatch[0], `~${hours} घंटे में ${dir} से आ रहा है`);
    } else if (locale === "zh-CN") {
      return rawText.replace(arriveMatch[0], `约 ${hours} 小时后自 ${dir} 抵达`);
    } else if (locale === "zh-TW") {
      return rawText.replace(arriveMatch[0], `約 ${hours} 小時後自 ${dir} 抵達`);
    } else if (locale === "ja") {
      return rawText.replace(arriveMatch[0], `約 ${hours} 時間後に ${dir} から到達`);
    } else if (locale === "es") {
      return rawText.replace(arriveMatch[0], `llegando en ~${hours}h desde el ${dir}`);
    } else if (locale === "fr") {
      return rawText.replace(arriveMatch[0], `arrivant dans ~${hours}h depuis ${dir}`);
    } else if (locale === "de") {
      return rawText.replace(arriveMatch[0], `trifft in ~${hours}h aus ${dir} ein`);
    }
  }

  // Pattern: LIVE WEATHER INTELLIGENCE • CITY
  const lwiMatch = trimmed.match(/^LIVE WEATHER INTELLIGENCE\s*•\s*(.+)$/i);
  if (lwiMatch) {
    const lwiTrans = pMap["Live Weather Intelligence"] || t("live_weather_intelligence", locale) || "Live Weather Intelligence";
    return rawText.replace(trimmed, `${lwiTrans.toUpperCase()} • ${lwiMatch[1]}`);
  }

  // Pattern: ... limiting comfort
  if (trimmed.includes("limiting comfort")) {
    const comfortTrans = pMap["limiting comfort"] || t("limiting_comfort", locale) || "limiting comfort";
    let res = rawText.replace("limiting comfort", comfortTrans);
    ["Temperature", "Humidity", "Wind", "Air Quality", "Precipitation", "Cloud Cover", "UV"].forEach(param => {
      const pTrans = pMap[param] || t(param.toLowerCase().replace(/\s+/g, "_"), locale);
      if (pTrans) res = res.replace(new RegExp(`\\b${param}\\b`, "g"), pTrans);
    });
    return res;
  }

  return rawText;
}

/**
 * Recursively translates all visible text nodes, placeholders, titles, aria-labels,
 * and select options within a DOM element tree.
 */
export function translateDOM(root = (typeof document !== "undefined" ? document.body : null), locale = detectLocale()) {
  if (!root || typeof document === "undefined") return;
  if (!locale) locale = detectLocale();

  // 1. Direct explicit translations for known key UI targets
  const targetMap = {
    copyAddressBtnText: "copy",
    toggleAddressCardText: "details",
    discoveriesHeaderTitle: "live_weather_intelligence_safety",
    settingsUnitsLabel: "units_metric",
    settingsUnitsSub: "units_metric_sub",
    settingsAppLanguageLabel: "settings_app_language",
    settingsAppLanguageSub: "settings_app_language_sub",
    elevationLegendTitle: "elevation_key"
  };
  for (const [id, key] of Object.entries(targetMap)) {
    const el = root.querySelector ? root.querySelector("#" + id) : document.getElementById(id);
    if (el) el.textContent = t(key, locale) || el.textContent;
  }
  const briefingBtn = root.querySelector ? root.querySelector("#briefingBtn") : document.getElementById("briefingBtn");
  if (briefingBtn) briefingBtn.textContent = `📡 ${t("generate_briefing", locale) || "Generate Briefing"}`;

  // 2. Translate <select> options (except settingsAppLanguageSelect)
  try {
    const selects = root.querySelectorAll ? root.querySelectorAll("select:not(#settingsAppLanguageSelect)") : [];
    selects.forEach(sel => {
      for (const opt of sel.options) {
        if (!opt.getAttribute("data-orig-text")) {
          opt.setAttribute("data-orig-text", opt.text);
        }
        const orig = opt.getAttribute("data-orig-text");
        const trans = translateText(orig, locale);
        if (trans && trans !== orig) {
          opt.text = trans;
        } else if (locale === "en" && orig) {
          opt.text = orig;
        }
      }
    });
  } catch (_) {}

  // 3. TreeWalker for all text nodes
  try {
    const walker = document.createTreeWalker(
      root,
      NodeFilter.SHOW_TEXT,
      {
        acceptNode(node) {
          if (!node.nodeValue || !node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
          const parent = node.parentElement;
          if (!parent) return NodeFilter.FILTER_REJECT;
          const tag = parent.tagName.toLowerCase();
          if (tag === "script" || tag === "style" || tag === "textarea" || tag === "code" || tag === "pre" || tag === "option") {
            return NodeFilter.FILTER_REJECT;
          }
          if (parent.closest && (parent.closest("#settingsAppLanguageSelect") || parent.classList?.contains("notranslate"))) {
            return NodeFilter.FILTER_REJECT;
          }
          return NodeFilter.FILTER_ACCEPT;
        }
      }
    );

    const textNodes = [];
    while (walker.nextNode()) {
      textNodes.push(walker.currentNode);
    }

    for (const node of textNodes) {
      if (node._origText == null) {
        node._origText = node.nodeValue;
      }
      const orig = node._origText;
      const translated = translateText(orig, locale);
      if (translated && translated !== orig) {
        node.nodeValue = translated;
      } else if (locale === "en" && orig) {
        node.nodeValue = orig;
      }
    }
  } catch (err) {
    /* ignore tree walker error */
  }

  // 4. Attributes: placeholder, title, aria-label
  try {
    const attrElements = root.querySelectorAll ? root.querySelectorAll("[placeholder], [title], [aria-label]") : [];
    attrElements.forEach(el => {
      if (el.id === "settingsAppLanguageSelect") return;
      ["placeholder", "title", "aria-label"].forEach(attr => {
        const val = el.getAttribute(attr);
        if (val && val.trim()) {
          const origKey = `data-orig-${attr}`;
          const origVal = el.getAttribute(origKey) || val;
          if (!el.hasAttribute(origKey)) el.setAttribute(origKey, origVal);
          const transVal = translateText(origVal, locale);
          if (transVal && transVal !== origVal) {
            el.setAttribute(attr, transVal);
          } else if (locale === "en") {
            el.setAttribute(attr, origVal);
          }
        }
      });
    });
  } catch (_) {}
}

